export function buildPlan(
  region: RegionKey,
  diet: DietKey,
  goal: GoalKey,
  baseKcal: number
) {
  const meals = KITCHEN[region][diet];
  const g = GOALS.find((x) => x.key === goal)!;
  return {
    meals,
    kcal: Math.max(1200, baseKcal + g.kcal),
    focus: g.focus,
    goalLabel: g.label,
  };
}

/* ==================================================================
   MEAL LIBRARY
   Categorisation is the point here. The primary axis is the one every
   Indian kitchen already sorts by: vegetarian or not, carried by the
   FSSAI food mark (green circle / brown triangle). Shape as well as
   colour, so the category survives colour blindness and greyscale.
   ================================================================== */

export type FoodCategory = "veg" | "nonveg";
export type MealTime = "breakfast" | "lunch" | "dinner" | "snack";
/** Sub-categories. `vegan` and `jain` are always subsets of `veg`. */
export type DietTag = "vegan" | "jain" | "egg" | "highProtein" | "lowGi" | "ironRich";

export type SubscriptionTier = "free" | "premium" | "enterprise";

/**
 * Which shelf of the library a meal sits on.
 *
 * `classic` is the regional Indian canon: dishes cooked at home, filed by the
 * region that cooks them. `genz` is the modern high-protein shelf — bowls,
 * wraps and salads that answer a gym target rather than a regional tradition,
 * which is why those carry no `region`.
 */
export type CollectionKey = "classic" | "genz";

export const COLLECTIONS: { key: CollectionKey; label: Bi; blurb: Bi }[] = [
  {
    key: "classic",
    label: { en: "Indian classics", hi: "भारतीय क्लासिक" },
    blurb: {
      en: "The regional canon, filed by the region that cooks it.",
      hi: "क्षेत्रीय रसोई, उसी क्षेत्र के नाम से।",
    },
  },
  {
    key: "genz",
    label: { en: "Gen-Z high protein", hi: "जेन-Z हाई प्रोटीन" },
    blurb: {
      en: "Bowls, wraps and salads built to hit a protein target.",
      hi: "प्रोटीन लक्ष्य के लिए बने बाउल, रैप और सलाद।",
    },
  },
];

export const COLLECTION_LABEL: Record<CollectionKey, Bi> = {
  classic: { en: "Indian classics", hi: "भारतीय क्लासिक" },
  genz: { en: "Gen-Z high protein", hi: "जेन-Z हाई प्रोटीन" },
};

export type MealPlanItem = {
  id: string;
  name: Bi;
  /** Absent on `genz` meals: they are pan-Indian, with no home region. */
  region?: RegionKey;
  time: MealTime;
  category: FoodCategory;
  tags: DietTag[];
  /** Defaults to `classic` when unset. */
  collection?: CollectionKey;
  kcal: number;
  macros: Macros;
  note: Bi;
  photo?: string;
  tier?: SubscriptionTier; // 'free' = Poshan (free), 'premium' = Poshan Home
};

